import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.D1JEzK2q.js";const k=JSON.parse('{"title":"Slack","description":"","frontmatter":{},"headers":[],"relativePath":"channels/slack.md","filePath":"channels/slack.md"}'),n={name:"channels/slack.md"};function i(r,e,c,d,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="slack" tabindex="-1">Slack <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Slack&quot;">​</a></h1><p>Slack connects using an app&#39;s Bot User OAuth Token and Signing Secret. The gateway receives signed HTTP Events API requests. Socket Mode is not used.</p><h2 id="create-the-slack-app" tabindex="-1">Create the Slack app <a class="header-anchor" href="#create-the-slack-app" aria-label="Permalink to &quot;Create the Slack app&quot;">​</a></h2><p>You need a workspace where you can install apps, an existing gateway agent, and a public HTTPS webhook URL.</p><ol><li>Open <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">Your Apps</a>, create an app from scratch, and choose the workspace.</li><li>Under <strong>OAuth &amp; Permissions</strong>, configure Bot Token Scopes for the features below.</li><li>Install the app to the workspace, completing any workspace administrator approval. Copy the <strong>Bot User OAuth Token</strong> (<code>xoxb-...</code>). Reinstall after changing scopes.</li><li>Under <strong>Basic Information → App Credentials</strong>, copy the <strong>Signing Secret</strong>.</li></ol><p>Use the bot token, not an app-level Socket Mode token or incoming-webhook URL. Slack documents <a href="https://docs.slack.dev/authentication/tokens/" target="_blank" rel="noreferrer">token types</a> and <a href="https://docs.slack.dev/authentication/verifying-requests-from-slack/" target="_blank" rel="noreferrer">request signing</a>.</p><table tabindex="0"><thead><tr><th>Bot scope</th><th>Gateway feature</th></tr></thead><tbody><tr><td><code>chat:write</code></td><td>Send replies and controls</td></tr><tr><td><code>im:history</code></td><td>Receive <code>message.im</code> direct-message events</td></tr><tr><td><code>app_mentions:read</code></td><td>Receive <code>app_mention</code> channel events</td></tr><tr><td><code>reactions:write</code></td><td>Add/remove processing acknowledgements</td></tr><tr><td><code>files:read</code></td><td>Download attached images and audio</td></tr><tr><td><code>files:write</code></td><td>Upload outgoing files/voice</td></tr><tr><td><code>users:read</code></td><td>Resolve display names for pending senders</td></tr><tr><td><code>commands</code></td><td>Registered slash commands</td></tr></tbody></table><p>Scopes authorize specific platform actions; see Slack&#39;s <a href="https://docs.slack.dev/reference/scopes/" target="_blank" rel="noreferrer">scope reference</a>. Grant the features you intend to use, then verify the token&#39;s installed scopes if Slack returns <code>missing_scope</code>.</p><h2 id="connect-the-gateway" tabindex="-1">Connect the gateway <a class="header-anchor" href="#connect-the-gateway" aria-label="Permalink to &quot;Connect the gateway&quot;">​</a></h2><p>Run <code>claude-gateway agents update --agent assistant</code>, choose Slack, and enter both credentials. The API validates the token with <code>auth.test</code> when saving it. The agent configuration fragment is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;slack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;botToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${SLACK_BOT_TOKEN}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;signingSecret&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${SLACK_SIGNING_SECRET}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dmPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dmAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;groupPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;groupAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;requireMention&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;pairing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The corresponding agent PATCH credential fields are <code>slack_bot_token</code> and <code>slack_signing_secret</code>; provide both together. Manual configuration edits require a restart with the referenced variables in the gateway environment.</p><p>In <strong>Event Subscriptions</strong>, enable events and set the Request URL to:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://gateway.example.com/gateway/webhooks/slack/assistant</span></span></code></pre></div><p>Adjust <code>/gateway</code> for your public proxy path. Disable Socket Mode. Subscribe to bot events <code>message.im</code> and <code>app_mention</code>, save, and reinstall if prompted. The gateway answers Slack&#39;s signed URL-verification challenge. See <a href="https://docs.slack.dev/apis/events-api/using-http-request-urls/" target="_blank" rel="noreferrer">Events API setup</a>.</p><h2 id="approve-the-conversation" tabindex="-1">Approve the conversation <a class="header-anchor" href="#approve-the-conversation" aria-label="Permalink to &quot;Approve the conversation&quot;">​</a></h2><p>DM the app. Open its gateway Slack settings, compare the received pairing code with the pending entry, and add the Slack user ID to <code>dmAllowlist</code>. Send a second DM to confirm a reply. IDs are stable <code>U...</code> values, not display names.</p><p>For a channel, invite the app, mention it, then approve that channel&#39;s stable ID in <code>groupAllowlist</code>. Slack calls this a channel, but the configuration deliberately uses <code>groupPolicy</code> and <code>groupAllowlist</code>. Under <code>requireMention: true</code>, use an explicit app mention. Subscribing only to <code>app_mention</code> means ordinary channel messages never arrive even if the gateway mention gate is disabled.</p><p>Administrators can inspect <code>GET /api/v1/agents/assistant/slack/pending</code>, then PATCH <code>slack_dm_allowlist</code> or <code>slack_group_allowlist</code> on the agent. Include already approved IDs because these fields replace their arrays. Other policy API fields are <code>slack_dm_policy</code>, <code>slack_group_policy</code>, <code>slack_require_mention</code> and <code>slack_pairing</code>. The CLI&#39;s Telegram/Discord approval command does not approve Slack users.</p><h2 id="enable-chat-controls-and-voice" tabindex="-1">Enable chat controls and voice <a class="header-anchor" href="#enable-chat-controls-and-voice" aria-label="Permalink to &quot;Enable chat controls and voice&quot;">​</a></h2><p>With <code>gateway.orchestration: true</code>, register these commands under <strong>Slash Commands</strong>, each with the same signed webhook Request URL: <code>/session</code>, <code>/sessions</code>, <code>/voice</code>, <code>/voices</code>, <code>/tasks</code>, <code>/stop</code>, <code>/help</code>. Enable <strong>Interactivity &amp; Shortcuts</strong> and set its Request URL to that webhook too, so button actions reach the gateway. Configuring Events API alone does not register slash commands or interactive callbacks.</p><p>You can also send <code>@bot /command</code> messages through the Events API.</p><p>The gateway accepts signed JSON events and Slack&#39;s form-encoded slash commands/interactions. Access rules apply to commands too. Session, task and voice controls use Slack Block Kit buttons. <code>/voice on</code>, <code>/voice auto</code>, <code>/voice off</code> choose Always, voice-input-only and Off; <code>/voices</code> chooses a voice. These require the agent&#39;s <a href="/claude-gateway/guide/voice.html">voice setup</a>; enabling voice does not change the chat&#39;s default Off preference.</p><p>Images and audio attachments can reach the agent; voice transcription requires orchestration and enabled voice notes. File access needs <code>files:read</code>. The connector has no native Slack typing implementation; processing reactions and task controls provide feedback instead.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>URL verification fails</td><td>Saved signing secret, exact public route, Socket Mode off, no login redirect</td></tr><tr><td>Webhook <code>401</code></td><td>Raw body/signature headers preserved; system clock within the five-minute replay window</td></tr><tr><td><code>invalid_auth</code> or <code>token_revoked</code></td><td>Correct installed <code>xoxb-...</code> token; update after reinstall/revocation</td></tr><tr><td>DMs work, channel silent</td><td>App invited, <code>app_mention</code> subscribed, channel approved, explicit mention</td></tr><tr><td>Text works, file/voice fails</td><td>File scopes, audio configuration and provider credentials</td></tr><tr><td>Slash command unknown</td><td>Register it in Slack with the gateway Request URL; enable orchestration</td></tr><tr><td>Buttons do nothing</td><td>Interactivity URL configured; sender has channel access</td></tr><tr><td>Missing reaction or user label</td><td><code>reactions:write</code> or <code>users:read</code> scope; reinstall after adding it</td></tr></tbody></table><p>Implementation references: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/slack-webhook-router.ts" target="_blank" rel="noreferrer">Slack webhook</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/slack-client.ts" target="_blank" rel="noreferrer">Slack client</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/slack-access.ts" target="_blank" rel="noreferrer">access gate</a>.</p>`,27)])])}const g=t(n,[["render",i]]);export{k as __pageData,g as default};
